         p = (amzTexture(tex, p.yz)*n.x + amzTexture(tex, p.zx)*n.y + amzTexture(tex, p.xy)*n.z).xyz;
            return p*p;
        }
        float3 tri(in float3 x){return abs(x-floor(x)-.5);}
        float3 triSmooth(in float3 x){return cos(x*6.2831853)*0.25+0.25;}
        float surfFunc(in float3 p){
            float n = dot(tri(p*0.15 + tri(p.yzx*0.075)), float3(0.444));
