            p.yz = float2(p.y + p.z, p.z - p.y) * 0.866;
            p.xz = float2(p.x + p.z, p.z - p.x) * 0.866;
            n += dot(tri(p*0.225 + tri(p.yzx*0.1125)), float3(0.222));
            return abs(n-0.5)*1.9 + (1.0 - abs(sin(n*9.0)))*0.05;
        }
        float2 path(in float z){ float s = sin(z/36.0)*cos(z/18.0); return float2(0.0, 0.0); }
        float map(float3 p){
             return p.y - surfFunc(p)*amzp_XXA;
        }
        float3 doBumpMap( int tex, in float3 p, in float3 nor, float bumpfactor){
            const float eps = 0.001;
            float3 grad = float3( getGrey(tex3D(tex, float3(p.x-eps, p.y, p.z), nor)),
                              getGrey(tex3D(tex, float3(p.x, p.y-eps, p.z), nor)),
                              getGrey(tex3D(tex, float3(p.x, p.y, p.z-eps), nor)));
            grad = (grad - getGrey(tex3D(tex, p , nor)))/eps;
            grad -= nor*dot(nor, grad);
            return normalize( nor + grad*bumpfactor );
        }
        float3 getNormal( in float3 p ){
            float2 e = float2(0.5773,-0.5773)*0.001;
            return normalize( e.xyy*map(p+e.xyy ) + e.yyx*map(p+e.yyx ) + e.yxy*map(p+e.yxy ) + e.xxx*map(p+e.xxx ));
        }
        float calculateAO(float3 p, float3 n){
            const float AO_SAMPLES = 5.0;
            float r = 0.0, w = 1.0, d;
            for (float i=1.0; i<AO_SAMPLES+1.1; i++){
                d = i/AO_SAMPLES;
                r += w*(d - map(p + n*d));
                w *= amzp_XXB;
            }
            return 1.0-clamp(r,0.0,1.0);
        }
        float curve(in float3 p, in float w){
            float2 e = float2(-1.0, 1.0)*w;
            float t1 = map(p + e.yxx), t2 = map(p + e.xxy);
            float t3 = map(p + e.xyx), t4 = map(p + e.yyy);
            return 0.125/(w*w) *(t1 + t2 + t3 + t4 - 4.0*map(p));
        }
        float3 blackbodyPalette(float t){
            t *= 3200.0;
            float cx = (0.860117757 + 1.54118254e-4*t + 1.28641212e-7*t*t)/(1.0 + 8.42420235e-4*t + 7.08145163e-7*t*t);
