                    else if( int(amzp_typeX)==1 ) {
                texCol = tex3D(1, sp*tSize0, sn); }
                    else if( int(amzp_typeX)==2 ) {
                texCol = tex3D(2, sp*tSize0, sn); }
                    else if( int(amzp_typeX)==3 ) {
                texCol = tex3D(3, sp*tSize0, sn); }
                    else if( int(amzp_typeX)==4 ) {
                texCol = tex3D(4, sp*tSize0, sn); }
                    else if( int(amzp_typeX)==5 ) {
                texCol = tex3D(5, sp*tSize0, sn); }
             float ao = calculateAO(sp, sn);
